```tsx
import { Button } from "@/components/ui/button";
import { Card, CardContent } from "@/components/ui/card";
import { MapPin, Building2, Clock, DollarSign } from "lucide-react";
import { formatDistanceToNow } from "date-fns";

interface JobListingCardProps {
  id: string;
  title: string;
  location: string | null;
  department: string | null;
  employmentType: string | null;
  salaryRange: string | null;
  createdAt: string;
  brandColor: string;
  onApply: (jobId: string) => void;
}

export default function JobListingCard({ id, title, location, department, employmentType, salaryRange, createdAt, brandColor, onApply }: JobListingCardProps) {
  const metadata = [
    location && { icon: MapPin, text: location },
    department && { icon: Building2, text: department },
    employmentType && { icon: Clock, text: employmentType },
    salaryRange && { icon: DollarSign, text: salaryRange },
  ].filter(Boolean) as { icon: typeof MapPin; text: string }[];

  return (
    <Card className="group hover:shadow-md transition-shadow duration-200 border border-border">
      <CardContent className="p-5">
        <div className="flex items-start justify-between gap-4">
          <div className="space-y-2 min-w-0 flex-1">
            <h3 className="text-lg font-semibold text-foreground leading-tight">{title || "Untitled Position"}</h3>
            {metadata.length > 0 && (
              <div className="flex flex-wrap items-center gap-x-4 gap-y-1">
                {metadata.map((m, i) => (
                  <span key={i} className="flex items-center gap-1 text-sm text-muted-foreground">
                    <m.icon className="h-3.5 w-3.5 shrink-0" />
                    {m.text}
                  </span>
                ))}
              </div>
            )}
            <p className="text-xs text-muted-foreground/60">
              Posted {formatDistanceToNow(new Date(createdAt), { addSuffix: true })}
            </p>
          </div>
          <Button
            className="shrink-0 text-white"
            style={{ backgroundColor: brandColor }}
            onClick={() => onApply(id)}
          >
            Apply Now
          </Button>
        </div>
      </CardContent>
    </Card>
  );
}
```

## File 2: Create `src/pages/CareerPage.tsx`

Public page — NO auth, NO sidebar. Read `src/pages/Apply.tsx` for the public page pattern.

```tsx
import { useState, useEffect } from "react";
import { useParams, useNavigate, Link } from "react-router-dom";
import { useQuery } from "@tanstack/react-query";
import { supabase } from "@/integrations/supabase/client";
import { Skeleton } from "@/components/ui/skeleton";
import { Badge } from "@/components/ui/badge";
import { Briefcase, Layers } from "lucide-react";
import JobListingCard from "@/components/career/JobListingCard";

interface CareerConfig {
  company_name: string;
  logo_url: string | null;
  brand_color: string;
  tagline: string | null;
  about: string | null;
}

interface CareerJob {
  id: string;
  title: string;
  location: string | null;
  department: string | null;
  employment_type: string | null;
  salary_range: string | null;
  created_at: string;
}

export default function CareerPage() {
  const { slug } = useParams<{ slug: string }>();
  const navigate = useNavigate();
  const [selectedDept, setSelectedDept] = useState<string | null>(null);

  const { data, isLoading } = useQuery({
    queryKey: ["career-page", slug],
    queryFn: async () => {
      if (!slug) return null;
      const { data, error } = await supabase.rpc("get_career_page", { p_slug: slug });
      if (error) throw error;
      return data as { config: CareerConfig; jobs: CareerJob[] } | null;
    },
    enabled: !!slug,
    staleTime: 60_000,
  });

  const config = data?.config;
  const jobs = data?.jobs ?? [];
  const brandColor = config?.brand_color ?? "#6366f1";

  const departments = [...new Set(jobs.map(j => j.department).filter(Boolean))] as string[];
  const filteredJobs = selectedDept ? jobs.filter(j => j.department === selectedDept) : jobs;

  useEffect(() => {
    if (config) {
      document.title = `Careers at ${config.company_name} | Rankora`;
    }
    return () => { document.title = "Rankora"; };
  }, [config]);

  const handleApply = (jobId: string) => navigate(`/apply/${jobId}`);

  // Loading state
  if (isLoading) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <header className="border-b border-border">
          <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
            <Skeleton className="h-8 w-8 rounded" />
            <Skeleton className="h-5 w-32" />
          </div>
        </header>
        <div className="max-w-4xl mx-auto px-4 py-12 w-full space-y-4">
          <Skeleton className="h-8 w-64 mx-auto" />
          <Skeleton className="h-4 w-48 mx-auto" />
          <div className="space-y-4 mt-8">
            {[1, 2, 3].map(i => <Skeleton key={i} className="h-24 w-full rounded-xl" />)}
          </div>
        </div>
      </div>
    );
  }

  // Not found
  if (!config) {
    return (
      <div className="min-h-screen bg-background flex flex-col">
        <header className="border-b border-border">
          <div className="max-w-4xl mx-auto px-4 py-4">
            <Link to="/" className="flex items-center gap-2 text-sm font-semibold">
              <Layers className="h-5 w-5 text-primary" /> Rankora
            </Link>
          </div>
        </header>
        <main className="flex-1 flex items-center justify-center px-4 py-16">
          <div className="text-center space-y-4">
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
              <Briefcase className="h-7 w-7 text-muted-foreground" />
            </div>
            <h1 className="text-xl font-semibold">Career page not found</h1>
            <p className="text-sm text-muted-foreground">This career page may have been removed or is not yet active.</p>
            <Link to="/" className="text-sm font-medium text-primary hover:text-primary/80 transition-colors">Back to Rankora</Link>
          </div>
        </main>
      </div>
    );
  }

  // Active page
  return (
    <div className="min-h-screen bg-background flex flex-col">
      {/* Header */}
      <header className="sticky top-0 z-10 bg-background/95 backdrop-blur border-b border-border">
        <div className="max-w-4xl mx-auto px-4 py-4 flex items-center gap-3">
          {config.logo_url && (
            <img src={config.logo_url} alt={config.company_name} className="h-8 w-8 rounded object-cover" />
          )}
          <span className="font-semibold text-lg text-foreground">{config.company_name}</span>
        </div>
      </header>

      {/* Hero */}
      <div className="py-12 px-4" style={{ backgroundColor: brandColor + "0D" }}>
        <div className="max-w-4xl mx-auto text-center space-y-3">
          <h1 className="text-3xl font-bold text-foreground">{config.company_name}</h1>
          {config.tagline && <p className="text-lg text-muted-foreground">{config.tagline}</p>}
          {config.about && <p className="text-sm text-muted-foreground max-w-2xl mx-auto leading-relaxed mt-2">{config.about}</p>}
          <Badge variant="secondary" className="mt-4 text-sm" style={{ borderColor: brandColor + "40" }}>
            {jobs.length} Open Position{jobs.length !== 1 ? "s" : ""}
          </Badge>
        </div>
      </div>

      {/* Department filter */}
      {departments.length > 1 && (
        <div className="max-w-4xl mx-auto px-4 pt-6 flex gap-2 flex-wrap">
          <button
            onClick={() => setSelectedDept(null)}
            className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
              !selectedDept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
            }`}
            style={!selectedDept ? { backgroundColor: brandColor } : undefined}
          >
            All ({jobs.length})
          </button>
          {departments.map(dept => (
            <button
              key={dept}
              onClick={() => setSelectedDept(dept)}
              className={`px-3 py-1.5 rounded-full text-xs font-medium transition-colors ${
                selectedDept === dept ? "text-white" : "bg-muted text-muted-foreground hover:bg-muted/80"
              }`}
              style={selectedDept === dept ? { backgroundColor: brandColor } : undefined}
            >
              {dept} ({jobs.filter(j => j.department === dept).length})
            </button>
          ))}
        </div>
      )}

      {/* Job listings */}
      <main className="flex-1 max-w-4xl mx-auto px-4 py-6 w-full">
        {filteredJobs.length === 0 ? (
          <div className="text-center py-16 space-y-3">
            <div className="w-14 h-14 rounded-full bg-muted flex items-center justify-center mx-auto">
              <Briefcase className="h-7 w-7 text-muted-foreground/40" />
            </div>
            <h2 className="text-base font-medium text-foreground">No open positions right now</h2>
            <p className="text-sm text-muted-foreground">Check back soon for new opportunities.</p>
          </div>
        ) : (
          <div className="grid gap-4">
            {filteredJobs.map(job => (
              <JobListingCard
                key={job.id}
                id={job.id}
                title={job.title}
                location={job.location}
                department={job.department}
                employmentType={job.employment_type}
                salaryRange={job.salary_range}
                createdAt={job.created_at}
                brandColor={brandColor}
                onApply={handleApply}
              />
            ))}
          </div>
        )}
      </main>

      {/* Footer */}
      <footer className="py-6 text-center border-t border-border">
        <p className="text-xs text-muted-foreground">
          Powered by{" "}
          <Link to="/" className="text-primary font-medium hover:text-primary/80 transition-colors">Rankora</Link>
        </p>
      </footer>
    </div>
  );
}
```

